pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller.code.length == 0);
        vm.assume(caller != address(0));
        // Ensure caller has a Bank that supports the token
        Bank b = new Bank();
        // The caller in the test must be the Bank's deployer? No - we need msg.sender == Bank(actor).
        // Actually, supportsToken modifier reads Bank(msg.sender).supportsToken(), so msg.sender MUST be a Bank contract.
        // The fuzzed address is an EOA, not a Bank contract. We need an adversarial helper that is a Bank.
        // The caller must be a contract that acts as a Bank and also calls airDrop.
        // We deploy a BankCaller helper that is a Bank and calls airDrop.
        BankCaller bc = new BankCaller(c);
        // The BankCaller has no balance initially.
        try bc.callAirDrop() returns (bytes memory) {
            // success
            // The balance of the BankCaller (which is the msg.sender inside airDrop) should be 20.
            assert(c.tokenBalance(address(bc)) == 20);
        } catch {
            // If revert, property holds vacuously, but we can assert that the state didn't change incorrectly.
            // No assertion needed for the revert case; property is satisfied because the rule is about successful airdrops.
        }
    }
}

contract BankCaller {
    C public c;
    constructor(C _c) { c = _c; }
    function callAirDrop() external {
        c.airDrop();
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

