import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. Bound to exclude precompiles and the zero address that could cause edge cases, but keep domain wide.
        vm.assume(caller != address(0) && uint160(caller) > 10);
        // 2. Deploy a Bank helper so supportsToken() check passes for the caller.
        Bank bank = new Bank();
        // Prank the caller as the bank so that msg.sender in supportsToken() returns the bank's address.
        // Actually c's modifier calls Bank(msg.sender).supportsToken(), so msg.sender must be the bank.
        // We need the caller to be the bank so that the supportsToken check passes.
        vm.prank(address(bank));
        c.airDrop();
        // After one successful airdrop, no account's balance can exceed 20.
        assertTrue(c.tokenBalance(address(bank)) <= 20);
    }
}

