pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address bank) public {
        vm.assume(caller != address(0));
        vm.assume(bank != address(0));
        vm.assume(caller != bank);

        // Adversarial bank that does NOT support the token
        FakeBank fakeBank = new FakeBank();
        vm.assume(bank != address(fakeBank));

        vm.prank(caller);
        vm.startPrank(caller);

        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // For a bad bank (fakeBank), the reference should revert; the buggy may succeed.
        // We embed the general rule using a legitimate vs illegitimate bank comparison:
        // 1. Deploy legitimate Bank
        Bank legitBank = new Bank();
        // 2. Prepare a caller with zero balance and no prank from bank (bank is checked via msg.sender in supportsToken modifier)
        // Actually, supportsToken() uses msg.sender which is the caller's address.
        // So we must prank as a bank contract to test the modifier logic.
        // However, the test's assertion must be general: if the caller has zero initial balance,
        // a call with a legitimate bank succeeds AND results in balance == 20.
        // For the buggy version, a call with a fake bank may also result in balance == 20.
        // So we re-do with precise setup:
        vm.prank(caller);
        vm.startPrank(caller);
        bool okLegit;
        try c.airDrop() {
            okLegit = true;
        } catch {
            okLegit = false;
        }
        vm.stopPrank();
        // Because caller hasn't been pranked as a bank, the modifier uses msg.sender == caller.
        // Legit bank check: requires caller to be a Bank returning correct supportsToken.
        // But caller is an EOA; an EOA's supportsToken() would fail (no code) -> revert.
        // So we need to call airdrop with msg.sender being a bank contract.
        // So we redo the whole test using prank as fakeBank and legitBank.
        // The assertion: after a call as fakeBank (adversarial), balance must be 0 (reference) but buggy may make it >0.
        // Or more precisely, for ANY caller EOA with zero balance, when airdrop is called by a bank that does NOT support the token,
        // the reference reverts, while buggy may succeed.
        // We use the deployed fakeBank, call airdrop pranked as fakeBank targeting caller (but airdrop's tokenBalance[msg.sender] uses msg.sender = fakeBank? Actually, airdrop uses msg.sender for tokenBalance. So we need the caller to be the bank, and tokenBalance[bank] to be set.
        // But token balance is for the caller (bank). The property is about tokenBalance of some key k; after call, tokenBalance[bank] may be non-zero for buggy.
        // We set the test to start with tokenBalance[bank] = 0, then call as fakeBank, and check tokenBalance[fakeBank].
        vm.startPrank(address(fakeBank));
        bool okBad;
        try c.airDrop() {
            okBad = true;
        } catch {
            okBad = false;
        }
        vm.stopPrank();
        // The universal property: if an unauthorized bank (one not supporting token) calls airdrop,
        // tokenBalance[unauthorizedBank] must not increase (reference always reverts).
        assertTrue(
            !okBad || c.tokenBalance(address(fakeBank)) == 0
        );
    }
}

contract FakeBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Wrong Token"));
    }
}

