pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, bool bankSupports) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        // Only test callers that have no balance to satisfy the hasNoBalance modifier
        vm.assume(c.tokenBalance(actor) == 0);

        // Deploy a Bank that may or may not support the token
        BankLike bank = bankSupports ? new LegitBank() : new FakeBank();
        vm.prank(actor);
        // The supportsToken modifier calls Bank(msg.sender).supportsToken();
        // Since msg.sender is the caller (actor), and the modifier checks keccak256("Nu Token") == Bank(msg.sender).supportsToken(),
        // we need the caller to be a contract that acts as a Bank.
        // However, the airDrop function has modifier supportsToken() which does Bank(msg.sender).supportsToken().
        // So msg.sender must be a Bank contract. We can't make actor a contract via fuzz directly.
        // Instead we deploy an Attacker contract that acts as the caller and is also a Bank.
        // But that would hardcode the scenario. Let us wrap the call via an Attacker that is itself a Bank.
    }
}

interface BankLike {
    function supportsToken() external pure returns (bytes32);
}

contract LegitBank is BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

contract FakeBank is BankLike {
    function supportsToken() external pure returns (bytes32) {
        return bytes32(0);
    }
}

