pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 fuzzSeed) public {
        vm.assume(attacker != address(0));
        vm.assume(
            attacker != address(this) &&
            attacker != address(c)
        );
        // Use fuzzSeed to derive a small reentrancy depth to avoid infinite recursion in test
        uint256 depth = (fuzzSeed % 3) + 1; // 1..3
        Attacker helper = new Attacker(c, depth);
        vm.deal(attacker, 0);
        vm.prank(attacker);
        helper.attack();
        uint256 bal = c.tokenBalance(attacker);
        assertTrue(bal == 20);
    }
}

contract Attacker {
    C public target;
    uint256 public count;
    uint256 public depth;
    constructor(C _target, uint256 _depth) {
        target = _target;
        depth = _depth;
    }
    function attack() external {
        count = 0;
        target.airDrop();
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    receive() external payable {
        if (count < depth) {
            count++;
            target.airDrop();
        }
    }
}
